// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address from, uint256 v, uint256 n) public {
        vm.assume(from != address(0));
        n = bound(n, 1, 4);
        v = bound(v, 1, type(uint128).max);
        address[] memory tos = new address[](n);
        for (uint256 i = 0; i < n; i++) {
            tos[i] = address(uint160(1000 + i));
        }
        // adversarial counterparty whose transferFrom call SUCCEEDS
        SucceedingToken tok = new SucceedingToken();
        bool ok;
        bool ret;
        try c.transfer(from, address(tok), tos, v) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
        }
        assertTrue(ok && ret, "completed transfer must return true");
    }
}

contract SucceedingToken {
    fallback() external payable {}
}
